TargetContent:
  "title": "Fittings: Den sikre form for retningsændring",
  "lead": "Hver retningsændring, hver forgrening er et kritisk punkt. K Aqua PP-R fittings omdanner disse punkter til systemets stærkeste led – takket være homogen molekylær sammensmeltning."
},
"intro": {
  "eyebrow": "Sømløs integration",
  "title": "Når to dele bliver til én.",
  "lead": "I modsætning til limede eller pressede rørforbindelser anvender vi termisk polyfusion. Fitting og rør opvarmes og smeltes sammen, så de danner én enkelt, uadskillelig struktur uden pakninger eller svage punkter."
},
"sticky": {
  "eyebrow": "Fitting Typer",
  "title": "Det komplette sortiment.",
  "lead": "Vores sortiment af fittings giver dig mulighed for at bygge enhver tænkelig geometri i rørnettet uden at gå på kompromis med gennemstrømning eller sikkerhed.",
  "items": [
    {
      "title": "Vinkler & Bøjninger",
      "desc": "45° og 90° vinkler til retningsændringer. Vores flow-optimerede design minimerer tryktabet i bøjningen markant sammenlignet med standard fittings."
    },
    {
      "title": "T-stykker & Forgreninger",
      "desc": "Lige og reducerede T-stykker til effektiv fordeling af væsker. Designet til at modstå de høje trykforskelle ved forgreninger."
    },
    {
      "title": "Muffer & Reduktioner",
      "desc": "Forbinder rør af samme eller forskellige diametre sikkert og permanent. Reduktioner er udformet konisk for at undgå kavitation."
    },
    {
      "title": "Endekapper & Propper",
      "desc": "Til sikker og tryktæt afslutning af rørledninger eller midlertidig forsegling af systemer under byggefasen."
    }
  ]
},
"bento": {
  "eyebrow": "Materialefordele",
