    {
      "title": "Glat inderside",
      "desc": "Sprøjtestøbningsprocessen garanterer en ekstremt glat indvendig overflade. Dette reducerer friktionstab til et minimum og forhindrer aflejringer (inkrustation)."
    },
    {
      "title": "UV-Beskyttelse (Valgfrit)",
      "desc": "Til udendørs installationer tilbyder vi sorte, UV-bestandige PP-R fittings, der modstår langvarig eksponering for sollys uden at miste mekanisk styrke."
    }
  ]
},
